import{_ as n,y as a,a as s,o as i,a2 as t,D as r}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Generative AI (Magic AI)","description":"","frontmatter":{},"headers":[],"relativePath":"configure/magic-ai.md","filePath":"configure/magic-ai.md","lastUpdated":1789441803000}'),g={name:"configure/magic-ai.md"};function h(d,e,l,c,u,p){const o=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="generative-ai-magic-ai" tabindex="-1">Generative AI (Magic AI) <a class="header-anchor" href="#generative-ai-magic-ai" aria-label="Permalink to &quot;Generative AI (Magic AI)&quot;">​</a></h1><p>Generative AI helps you write content and create images in the admin panel, and helps shoppers search with a photo, read reviews in their own language and get a thank-you message after an order. In the admin panel these features are called <strong>Magic AI</strong>, and they are all set up in one place: <strong>Configure &gt;&gt; Magic AI</strong>. The group has four screens: <strong>General</strong>, <strong>Providers</strong>, <strong>Admin Features</strong> and <strong>Storefront Features</strong>.</p><p>This page covers the setup only. What each feature does, and how to use it, is described in the <a href="./../generative-ai/introduction.html">Generative AI</a> section.</p>',3)),r(o,{src:"/images/configure/magic-ai-screens.png",alt:"The Magic AI group on the Configure page with its four screens"}),e[1]||(e[1]=t('<h2 id="turn-on-generative-ai-magic-ai" tabindex="-1">Turn on Generative AI (Magic AI) <a class="header-anchor" href="#turn-on-generative-ai-magic-ai" aria-label="Permalink to &quot;Turn on Generative AI (Magic AI)&quot;">​</a></h2><p><strong>Enabled</strong> is the master switch for Magic AI. Switch it on before you turn on any feature.</p><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong>.</li><li>In <strong>Settings</strong>, switch <strong>Enabled</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),r(o,{src:"/images/configure/magic-ai-general.png",alt:"Settings section of the Magic AI General screen with Enabled switched on"}),e[2]||(e[2]=t('<p>The switch applies to the whole store, not to one channel.</p><h2 id="connect-a-provider" tabindex="-1">Connect a provider <a class="header-anchor" href="#connect-a-provider" aria-label="Permalink to &quot;Connect a provider&quot;">​</a></h2><p>Magic AI sends each request to the provider of the model it uses. Bagisto supports eight providers, and you only need to connect the ones whose models you plan to use.</p><table tabindex="0"><thead><tr><th>Provider</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Anthropic</strong>, <strong>DeepSeek</strong>, <strong>Gemini</strong>, <strong>Groq</strong>, <strong>Mistral</strong>, <strong>OpenAI</strong> and <strong>xAI</strong></td><td>The <strong>API Key</strong> you create in your account on the provider&#39;s website.</td></tr><tr><td><strong>Ollama</strong></td><td>The <strong>Base URL</strong> of the server that runs your Ollama models, <code>http://localhost:11434</code> by default. Enter an <strong>API Key</strong> only if that server asks for one.</td></tr></tbody></table><p>Before you start, create an API key in your account on the provider&#39;s website.</p><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Providers</strong>.</li><li>In the provider&#39;s section, enter the <strong>API Key</strong>.</li><li>For <strong>Ollama</strong>, enter the <strong>Base URL</strong> of your Ollama server.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),r(o,{src:"/images/configure/magic-ai-providers.png",alt:"Providers screen with a section for each of the eight providers"}),e[3]||(e[3]=t('<p>Keys are masked on the screen. Provider settings apply to the whole store.</p><h2 id="enable-the-admin-features" tabindex="-1">Enable the admin features <a class="header-anchor" href="#enable-the-admin-features" aria-label="Permalink to &quot;Enable the admin features&quot;">​</a></h2><p>The admin features help you write and illustrate content while you work in the admin panel. Nothing they produce is added until you click <strong>Apply</strong>.</p><table tabindex="0"><thead><tr><th>Section</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Text Generation</strong></td><td>Makes the <strong>Magic AI</strong> button in the toolbar of the rich-text editors clickable, in editors such as product and category descriptions and CMS pages. While the feature is off, the button is greyed out. You describe what you need, choose a model and generate the text. See <a href="./../generative-ai/generate-content.html">Generate text content</a>.</td></tr><tr><td><strong>Image Generation</strong></td><td>Adds a <strong>Magic AI</strong> tile beside <strong>Add Image</strong> in the image fields of the admin panel, such as product and category images. You describe the image, choose a model and generate it. See <a href="./../generative-ai/generate-images.html">Generate product images</a>.</td></tr></tbody></table><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Admin Features</strong>.</li><li>In <strong>Text Generation</strong>, switch <strong>Enabled</strong> on.</li><li>In <strong>Providers</strong>, choose the providers whose text models admins can pick from.</li><li>In <strong>Image Generation</strong>, switch <strong>Enabled</strong> on.</li><li>In <strong>Providers</strong>, choose the providers whose image models admins can pick from: <strong>Gemini</strong>, <strong>OpenAI</strong> or <strong>xAI</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),r(o,{src:"/images/configure/magic-ai-admin-features.png",alt:"Admin Features screen with Text Generation and Image Generation switched on and providers chosen"}),e[4]||(e[4]=t('<p>The model list in each dialog shows only the models of the providers you choose here, so choose at least one provider whose key you have saved. The admin features apply to the whole store.</p><p>Roles don&#39;t limit these features. While they&#39;re on, every admin user who can open a rich-text editor or an image field can use the <strong>Magic AI</strong> button and tile, and each request is charged to your provider account.</p><h2 id="enable-the-storefront-features" tabindex="-1">Enable the storefront features <a class="header-anchor" href="#enable-the-storefront-features" aria-label="Permalink to &quot;Enable the storefront features&quot;">​</a></h2><p>The storefront features respond to what a shopper does: searching with a photo, reading a review or placing an order. Each is set per channel.</p><table tabindex="0"><thead><tr><th>Section</th><th>What it does</th></tr></thead><tbody><tr><td><strong>AI Image Search</strong></td><td>When a shopper searches with a photo, a model identifies the product in it, and the store searches the catalog for the first keyword the model suggests. The camera icon in the search bar comes from <strong>Image Search Option</strong> under <a href="./configurable-choices.html">Product Settings</a>, which must also be on. Without AI image search, photo search still works, using basic image recognition in the shopper&#39;s browser. See <a href="./../generative-ai/image-search.html">AI image search</a>.</td></tr><tr><td><strong>Review Translation</strong></td><td>Adds a <strong>Translate</strong> button to each review on the product page. It translates the review into the language the shopper is browsing in. See <a href="./../generative-ai/review-translation.html">Review translation</a>.</td></tr><tr><td><strong>Personalized Checkout Message</strong></td><td>Shows a thank-you message written for each order on the order confirmation page, based on the products ordered, the customer&#39;s name and the store&#39;s name. If the model can&#39;t be reached, the page shows its standard thank-you text instead. See <a href="./../generative-ai/checkout-message.html">Personalized checkout message</a>.</td></tr></tbody></table><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In the section of each feature you want, switch <strong>Enabled</strong> on.</li><li>Choose the <strong>Model</strong> the feature uses.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),r(o,{src:"/images/configure/magic-ai-storefront-features.png",alt:"Storefront Features screen with AI Image Search, Review Translation and Personalized Checkout Message switched on and a model chosen"}),e[5]||(e[5]=t("<p>Choose a model from a provider whose key you have saved. Until a <strong>Model</strong> is saved, the feature uses a default OpenAI model, which needs an OpenAI key.</p><p><strong>AI Image Search</strong> and <strong>Personalized Checkout Message</strong> work only while <strong>Enabled</strong> is also on under <strong>General</strong>. To stop review translation, switch <strong>Review Translation</strong> off: switching off <strong>Enabled</strong> under <strong>General</strong> doesn&#39;t hide the <strong>Translate</strong> button.</p>",2))])}const I=n(g,[["render",h]]);export{f as __pageData,I as default};
